// REST Assured: assert the status code and inspect the error
Response response = given()
        .contentType(ContentType.JSON)
        .body("{\"productId\": 10, \"quantity\": -1}")
.when()
        .post("https://api.example.com/orders");

int status = response.statusCode();
System.out.println("Status: " + status);

if (status == 503) {
    System.out.println("Service unavailable. Retry-After: " + response.header("Retry-After"));
} else if (status == 500) {
    System.out.println("Server error body: " + response.asString());
}

// A negative input should be rejected by validation, not crash the server
Assert.assertEquals(status, 400, "Invalid quantity should return 400 Bad Request");

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.*;

public class UserApiTest {
    private static RequestSpecification requestSpec;
    private static ResponseSpecification responseSpec;

    @BeforeClass
    public void setUp() {
        requestSpec = new RequestSpecBuilder()
                .setBaseUri("https://api.example.com")
                .setBasePath("/v1")
                .setContentType(ContentType.JSON)
                .addHeader("Authorization", "Bearer " + System.getenv("API_TOKEN"))
                .log(LogDetail.URI)
                .build();

        responseSpec = new ResponseSpecBuilder()
                .expectStatusCode(200)
                .expectContentType(ContentType.JSON)
                .expectResponseTime(lessThan(2000L))
                .build();
    }

    @Test
    public void getUser() {
        given()
                .spec(requestSpec)
                .pathParam("id", 7)                 // test-specific addition
        .when()
                .get("/users/{id}")
        .then()
                .spec(responseSpec)
                .body("id", equalTo(7))             // test-specific assertion
                .body("email", notNullValue());
    }

    @Test
    public void listUsers() {
        given()
                .spec(requestSpec)
                .queryParam("page", 1)
        .when()
                .get("/users")
        .then()
                .spec(responseSpec)
                .body("data.size()", greaterThan(0));
    }
}
